insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002161', 'having finished', '/ˈhævɪŋ ˈfɪnɪʃt/', 'phrase', 'tendo terminado', 'Having finished the report, she left the office early.', 'Tendo terminado o relatório, ela saiu do escritório mais cedo.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002162', 'having said that', '/ˈhævɪŋ sed ðæt/', 'phrase', 'dito isso', 'The plan is risky. Having said that, it could work.', 'O plano é arriscado. Dito isso, poderia funcionar.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002163', 'having considered', '/ˈhævɪŋ kənˈsɪdərd/', 'phrase', 'tendo considerado', 'Having considered all the options, the board approved the merger.', 'Tendo considerado todas as opções, a diretoria aprovou a fusão.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002164', 'having been', '/ˈhævɪŋ bɪn/', 'phrase', 'tendo sido', 'Having been warned twice, he finally changed his approach.', 'Tendo sido avisado duas vezes, ele finalmente mudou sua abordagem.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002165', 'not having', '/nɒt ˈhævɪŋ/', 'phrase', 'não tendo', 'Not having received a reply, she called the office directly.', 'Não tendo recebido resposta, ela ligou diretamente para o escritório.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002166', 'having done so', '/ˈhævɪŋ dʌn soʊ/', 'phrase', 'tendo feito isso', 'He reviewed the contract, and having done so, he signed it.', 'Ele revisou o contrato, e tendo feito isso, o assinou.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002167', 'while working', '/waɪl ˈwɜːrkɪŋ/', 'phrase', 'enquanto trabalhava', 'While working on the report, she found several errors.', 'Enquanto trabalhava no relatório, ela encontrou vários erros.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002168', 'before leaving', '/bɪˈfɔːr ˈliːvɪŋ/', 'phrase', 'antes de sair', 'Before leaving the office, always lock your computer.', 'Antes de sair do escritório, sempre tranque seu computador.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002169', 'after checking', '/ˈæftər ˈtʃekɪŋ/', 'phrase', 'depois de verificar', 'After checking the figures, the accountant approved the budget.', 'Depois de verificar os números, o contador aprovou o orçamento.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002170', 'upon arrival', '/əˈpɒn əˈraɪvəl/', 'phrase', 'ao chegar', 'Upon arrival, guests must present a valid ID.', 'Ao chegar, os hóspedes devem apresentar um documento de identidade válido.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002171', 'upon completion', '/əˈpɒn kəmˈpliːʃən/', 'phrase', 'ao concluir', 'Upon completion of the course, students receive a certificate.', 'Ao concluir o curso, os alunos recebem um certificado.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002172', 'on reflection', '/ɒn rɪˈflekʃən/', 'phrase', 'pensando bem', 'On reflection, the original plan seems safer.', 'Pensando bem, o plano original parece mais seguro.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002173', 'left unchecked', '/left ʌnˈtʃekt/', 'phrase', 'se não for verificado', 'Left unchecked, the small error grew into a major problem.', 'Se não for verificado, o pequeno erro se transforma em um grande problema.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002174', 'given the circumstances', '/ˈɡɪvən ðə ˈsɜːrkəmstænsɪz/', 'phrase', 'dadas as circunstâncias', 'Given the circumstances, the delay was understandable.', 'Dadas as circunstâncias, o atraso foi compreensível.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002175', 'once completed', '/wʌns kəmˈpliːtɪd/', 'phrase', 'uma vez concluído', 'Once completed, the report will be sent to all departments.', 'Uma vez concluído, o relatório será enviado a todos os departamentos.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002176', 'when asked', '/wen æskt/', 'phrase', 'quando perguntado', 'When asked about the delay, the manager apologized.', 'Quando perguntado sobre o atraso, o gerente se desculpou.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002177', 'if approved', '/ɪf əˈpruːvd/', 'phrase', 'se aprovado', 'If approved, the new policy will take effect in January.', 'Se aprovada, a nova política entrará em vigor em janeiro.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002178', 'unless stated otherwise', '/ənˈles ˈsteɪtɪd ˈʌðərwaɪz/', 'phrase', 'salvo indicação em contrário', 'Unless stated otherwise, all meetings start at nine.', 'Salvo indicação em contrário, todas as reuniões começam às nove.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002179', 'being late', '/ˈbiːɪŋ leɪt/', 'phrase', 'por estar atrasado', 'Being late for the interview, he apologized immediately.', 'Por estar atrasado para a entrevista, ele se desculpou imediatamente.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002180', 'there being', '/ðer ˈbiːɪŋ/', 'phrase', 'havendo', 'There being no further questions, the meeting was closed.', 'Não havendo mais perguntas, a reunião foi encerrada.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002181', 'seeing that', '/ˈsiːɪŋ ðæt/', 'phrase', 'visto que', 'Seeing that the deadline had passed, they extended it by a week.', 'Visto que o prazo tinha passado, eles o estenderam por uma semana.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002182', 'considering that', '/kənˈsɪdərɪŋ ðæt/', 'phrase', 'considerando que', 'Considering that the budget was limited, the results were impressive.', 'Considerando que o orçamento era limitado, os resultados foram impressionantes.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002183', 'assuming that', '/əˈsuːmɪŋ ðæt/', 'phrase', 'supondo que', 'Assuming that the data is correct, the forecast looks positive.', 'Supondo que os dados estejam corretos, a previsão parece positiva.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002184', 'in doing so', '/ɪn ˈduːɪŋ soʊ/', 'phrase', 'ao fazer isso', 'She simplified the process, and in doing so, saved the team hours.', 'Ela simplificou o processo, e ao fazer isso, economizou horas da equipe.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002185', 'that said', '/ðæt sed/', 'phrase', 'dito isso', 'The results were disappointing. That said, there is room for improvement.', 'Os resultados foram decepcionantes. Dito isso, há espaço para melhorias.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002186', 'all things considered', '/ɔːl θɪŋz kənˈsɪdərd/', 'phrase', 'considerando tudo', 'All things considered, the project was a success.', 'Considerando tudo, o projeto foi um sucesso.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002187', 'taking everything into account', '/ˈteɪkɪŋ ˈevriθɪŋ ˈɪntuː əˈkaʊnt/', 'phrase', 'levando tudo em consideração', 'Taking everything into account, we decided to postpone the launch.', 'Levando tudo em consideração, decidimos adiar o lançamento.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002188', 'as mentioned above', '/æz ˈmenʃənd əˈbʌv/', 'phrase', 'como mencionado acima', 'As mentioned above, the deadline cannot be extended.', 'Como mencionado acima, o prazo não pode ser estendido.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002189', 'bearing in mind', '/ˈberɪŋ ɪn maɪnd/', 'phrase', 'tendo em mente', 'Bearing in mind the risks, the team proceeded carefully.', 'Tendo em mente os riscos, a equipe prosseguiu com cuidado.', 'C1', array['participle-clauses']),
('30000000-0000-0000-0000-000000002190', 'with that in mind', '/wɪð ðæt ɪn maɪnd/', 'phrase', 'com isso em mente', 'With that in mind, we redesigned the entire process.', 'Com isso em mente, redesenhamos todo o processo.', 'C1', array['participle-clauses']);

