-- Lição 361: Orações reduzidas com "having" (having finished, having said that, having considered, having been, not having, having done so)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000361', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002161", "show_image": false}'),
('20000000-0000-0000-0000-000000000361', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002163", "show_image": false}'),
('20000000-0000-0000-0000-000000000361', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002165", "show_image": false}'),
('20000000-0000-0000-0000-000000000361', 'multiple_choice', 4, '{"question": "___ the report, she left the office early.", "audio_text": null, "options": ["Having finished", "Having been", "Not having"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000361', 'multiple_choice', 5, '{"question": "___ received a reply, she called the office directly.", "audio_text": null, "options": ["Not having", "Having said that", "Having done so"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000361', 'matching', 6, '{"pairs": [{"left": "having finished", "right": "tendo terminado"}, {"left": "having said that", "right": "dito isso"}, {"left": "having considered", "right": "tendo considerado"}, {"left": "having been", "right": "tendo sido"}, {"left": "not having", "right": "não tendo"}, {"left": "having done so", "right": "tendo feito isso"}]}'),
('20000000-0000-0000-0000-000000000361', 'fill_blank', 7, '{"sentence": "___ all the options, the board approved the merger.", "options": ["Having considered", "Not having", "Having said that"], "correct": "Having considered", "translation": "Tendo considerado todas as opções, a diretoria aprovou a fusão."}'),
('20000000-0000-0000-0000-000000000361', 'fill_blank', 8, '{"sentence": "___ warned twice, he finally changed his approach.", "options": ["Having been", "Having finished", "Not having"], "correct": "Having been", "translation": "Tendo sido avisado duas vezes, ele finalmente mudou sua abordagem."}'),
('20000000-0000-0000-0000-000000000361', 'word_order', 9, '{"words": ["He", "reviewed", "the", "contract", "and", "having", "done", "so", "he", "signed", "it"], "correct_sentence": "He reviewed the contract and having done so he signed it", "translation": "Ele revisou o contrato, e tendo feito isso, o assinou"}'),
('20000000-0000-0000-0000-000000000361', 'word_order', 10, '{"words": ["The", "plan", "is", "risky", "Having", "said", "that", "it", "could", "work"], "correct_sentence": "The plan is risky Having said that it could work", "translation": "O plano é arriscado. Dito isso, poderia funcionar"}'),
('20000000-0000-0000-0000-000000000361', 'reading', 11, '{"passage": "In formal writing, ''having'' plus a past participle replaces a longer clause with ''after'' or ''because''. ''Having finished the report, she left'' means the same as ''after she had finished the report, she left'', but sounds more concise. The negative form, ''not having'', works the same way, as in ''not having received a reply, she called the office''.", "translation": "Em textos formais, ''having'' mais particípio passado substitui uma oração mais longa com ''after'' ou ''because''. ''Having finished the report, she left'' significa o mesmo que ''after she had finished the report, she left'', mas soa mais conciso. A forma negativa, ''not having'', funciona da mesma forma, como em ''not having received a reply, she called the office''.", "question": "What does ''having finished the report, she left'' mean, according to the text?", "options": ["The same as ''after she had finished the report, she left''", "She never finished the report", "She left before finishing"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000361', 'listening', 12, '{"audio_text": "Having finished the report, she left the office early. Having been warned twice, he finally changed his approach. Not having received a reply, she called the office directly.", "question": "What did she do after not receiving a reply, according to the audio?", "options": ["She called the office directly", "She left the office early", "She warned the manager"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000361', 'dictation', 13, '{"audio_text": "Having finished the report, she left the office early.", "expected": "Having finished the report, she left the office early."}'),
('20000000-0000-0000-0000-000000000361', 'typing', 14, '{"prompt_pt": "Traduza: ''Tendo considerado todas as opções e tendo sido avisada dos riscos, ela decidiu esperar.''", "expected": "Having considered all the options and having been warned of the risks, she decided to wait.", "ai_review": true}'),

-- Lição 362: Reduções de tempo e sequência (while working, before leaving, after checking, upon arrival, upon completion, on reflection)
('20000000-0000-0000-0000-000000000362', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002167", "show_image": false}'),
('20000000-0000-0000-0000-000000000362', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002170", "show_image": false}'),
('20000000-0000-0000-0000-000000000362', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002172", "show_image": false}'),
('20000000-0000-0000-0000-000000000362', 'multiple_choice', 4, '{"question": "___ on the report, she found several errors.", "audio_text": null, "options": ["While working", "Upon arrival", "On reflection"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000362', 'multiple_choice', 5, '{"question": "___, guests must present a valid ID.", "audio_text": null, "options": ["Upon arrival", "Before leaving", "After checking"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000362', 'matching', 6, '{"pairs": [{"left": "while working", "right": "enquanto trabalhava"}, {"left": "before leaving", "right": "antes de sair"}, {"left": "after checking", "right": "depois de verificar"}, {"left": "upon arrival", "right": "ao chegar"}, {"left": "upon completion", "right": "ao concluir"}, {"left": "on reflection", "right": "pensando bem"}]}'),
('20000000-0000-0000-0000-000000000362', 'fill_blank', 7, '{"sentence": "___ of the course, students receive a certificate.", "options": ["Upon completion", "Before leaving", "While working"], "correct": "Upon completion", "translation": "Ao concluir o curso, os alunos recebem um certificado."}'),
('20000000-0000-0000-0000-000000000362', 'fill_blank', 8, '{"sentence": "___, the original plan seems safer.", "options": ["On reflection", "Upon arrival", "After checking"], "correct": "On reflection", "translation": "Pensando bem, o plano original parece mais seguro."}'),
('20000000-0000-0000-0000-000000000362', 'word_order', 9, '{"words": ["Before", "leaving", "the", "office", "always", "lock", "your", "computer"], "correct_sentence": "Before leaving the office always lock your computer", "translation": "Antes de sair do escritório, sempre tranque seu computador"}'),
('20000000-0000-0000-0000-000000000362', 'word_order', 10, '{"words": ["After", "checking", "the", "figures", "the", "accountant", "approved", "the", "budget"], "correct_sentence": "After checking the figures the accountant approved the budget", "translation": "Depois de verificar os números, o contador aprovou o orçamento"}'),
('20000000-0000-0000-0000-000000000362', 'reading', 11, '{"passage": "Time relationships can also be expressed with ''-ing'' clauses and prepositional phrases instead of full clauses with subjects. ''While working on the report'' replaces ''while she was working on the report'', and ''upon arrival'' replaces ''when guests arrive''. These reductions are common in instructions, policies and reports, where conciseness matters.", "translation": "Relações de tempo também podem ser expressas com orações em ''-ing'' e frases preposicionais em vez de orações completas com sujeito. ''While working on the report'' substitui ''while she was working on the report'', e ''upon arrival'' substitui ''when guests arrive''. Essas reduções são comuns em instruções, políticas e relatórios, onde a concisão importa.", "question": "Where are these time reductions common, according to the text?", "options": ["In poetry only", "In instructions, policies and reports", "In casual conversation only"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000362', 'listening', 12, '{"audio_text": "While working on the report, she found several errors. Upon arrival, guests must present a valid ID. On reflection, the original plan seems safer.", "question": "What must guests present upon arrival, according to the audio?", "options": ["A valid ID", "A certificate", "A budget report"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000362', 'dictation', 13, '{"audio_text": "Upon arrival, guests must present a valid ID.", "expected": "Upon arrival, guests must present a valid ID."}'),
('20000000-0000-0000-0000-000000000362', 'typing', 14, '{"prompt_pt": "Traduza: ''Ao chegar, verifique seus e-mails; ao concluir a tarefa, avise a equipe.''", "expected": "Upon arrival, check your emails; upon completion of the task, notify the team.", "ai_review": true}'),

-- Lição 363: Particípio passado em condição e passiva reduzida (left unchecked, given the circumstances, once completed, when asked, if approved, unless stated otherwise)
('20000000-0000-0000-0000-000000000363', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002173", "show_image": false}'),
('20000000-0000-0000-0000-000000000363', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002176", "show_image": false}'),
('20000000-0000-0000-0000-000000000363', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002178", "show_image": false}'),
('20000000-0000-0000-0000-000000000363', 'multiple_choice', 4, '{"question": "___, the small error grew into a major problem.", "audio_text": null, "options": ["Left unchecked", "Once completed", "If approved"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000363', 'multiple_choice', 5, '{"question": "___ about the delay, the manager apologized.", "audio_text": null, "options": ["When asked", "Given the circumstances", "Unless stated otherwise"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000363', 'matching', 6, '{"pairs": [{"left": "left unchecked", "right": "se não for verificado"}, {"left": "given the circumstances", "right": "dadas as circunstâncias"}, {"left": "once completed", "right": "uma vez concluído"}, {"left": "when asked", "right": "quando perguntado"}, {"left": "if approved", "right": "se aprovado"}, {"left": "unless stated otherwise", "right": "salvo indicação em contrário"}]}'),
('20000000-0000-0000-0000-000000000363', 'fill_blank', 7, '{"sentence": "___, the new policy will take effect in January.", "options": ["If approved", "When asked", "Left unchecked"], "correct": "If approved", "translation": "Se aprovada, a nova política entrará em vigor em janeiro."}'),
('20000000-0000-0000-0000-000000000363', 'fill_blank', 8, '{"sentence": "___, all meetings start at nine.", "options": ["Unless stated otherwise", "Once completed", "Given the circumstances"], "correct": "Unless stated otherwise", "translation": "Salvo indicação em contrário, todas as reuniões começam às nove."}'),
('20000000-0000-0000-0000-000000000363', 'word_order', 9, '{"words": ["Given", "the", "circumstances", "the", "delay", "was", "understandable"], "correct_sentence": "Given the circumstances the delay was understandable", "translation": "Dadas as circunstâncias, o atraso foi compreensível"}'),
('20000000-0000-0000-0000-000000000363', 'word_order', 10, '{"words": ["Once", "completed", "the", "report", "will", "be", "sent", "to", "all", "departments"], "correct_sentence": "Once completed the report will be sent to all departments", "translation": "Uma vez concluído, o relatório será enviado a todos os departamentos"}'),
('20000000-0000-0000-0000-000000000363', 'reading', 11, '{"passage": "Past participles can also reduce passive clauses, especially after conditions and time expressions. ''Left unchecked'' replaces ''if it is left unchecked'', and ''once completed'' replaces ''once it has been completed''. This pattern is very common in official documents, contracts and instructions, where the passive subject is understood from context.", "translation": "Particípios passados também podem reduzir orações passivas, especialmente depois de condições e expressões de tempo. ''Left unchecked'' substitui ''if it is left unchecked'', e ''once completed'' substitui ''once it has been completed''. Esse padrão é muito comum em documentos oficiais, contratos e instruções, onde o sujeito da passiva é entendido pelo contexto.", "question": "What does ''left unchecked'' replace, according to the text?", "options": ["''if it is left unchecked''", "''before it is checked''", "''after checking it''"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000363', 'listening', 12, '{"audio_text": "Left unchecked, the small error grew into a major problem. When asked about the delay, the manager apologized. If approved, the new policy will take effect in January.", "question": "What grew into a major problem, according to the audio?", "options": ["The small error", "The new policy", "The delay"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000363', 'dictation', 13, '{"audio_text": "If approved, the new policy will take effect in January.", "expected": "If approved, the new policy will take effect in January."}'),
('20000000-0000-0000-0000-000000000363', 'typing', 14, '{"prompt_pt": "Traduza: ''Se aprovado, o projeto começará em janeiro; salvo indicação em contrário, o prazo é de um mês.''", "expected": "If approved, the project will start in January; unless stated otherwise, the deadline is one month.", "ai_review": true}'),

