('20000000-0000-0000-0000-000000000364', 'multiple_choice', 4, '{"question": "___ for the interview, he apologized immediately.", "audio_text": null, "options": ["Being late", "There being", "In doing so"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000364', 'multiple_choice', 5, '{"question": "___ no further questions, the meeting was closed.", "audio_text": null, "options": ["There being", "Being late", "Seeing that"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000364', 'matching', 6, '{"pairs": [{"left": "being late", "right": "por estar atrasado"}, {"left": "there being", "right": "havendo"}, {"left": "seeing that", "right": "visto que"}, {"left": "considering that", "right": "considerando que"}, {"left": "assuming that", "right": "supondo que"}, {"left": "in doing so", "right": "ao fazer isso"}]}'),
('20000000-0000-0000-0000-000000000364', 'fill_blank', 7, '{"sentence": "___ the budget was limited, the results were impressive.", "options": ["Considering that", "There being", "In doing so"], "correct": "Considering that", "translation": "Considerando que o orçamento era limitado, os resultados foram impressionantes."}'),
('20000000-0000-0000-0000-000000000364', 'fill_blank', 8, '{"sentence": "___ the data is correct, the forecast looks positive.", "options": ["Assuming that", "Being late", "Seeing that"], "correct": "Assuming that", "translation": "Supondo que os dados estejam corretos, a previsão parece positiva."}'),
('20000000-0000-0000-0000-000000000364', 'word_order', 9, '{"words": ["Seeing", "that", "the", "deadline", "had", "passed", "they", "extended", "it", "by", "a", "week"], "correct_sentence": "Seeing that the deadline had passed they extended it by a week", "translation": "Visto que o prazo tinha passado, eles o estenderam por uma semana"}'),
('20000000-0000-0000-0000-000000000364', 'word_order', 10, '{"words": ["She", "simplified", "the", "process", "and", "in", "doing", "so", "saved", "the", "team", "hours"], "correct_sentence": "She simplified the process and in doing so saved the team hours", "translation": "Ela simplificou o processo, e ao fazer isso, economizou horas da equipe"}'),
('20000000-0000-0000-0000-000000000364', 'reading', 11, '{"passage": "Reasons and causes can also be expressed through participle clauses. ''Being late for the interview, he apologized'' explains the reason for the apology without using ''because''. ''There being'' is a formal way to introduce an existential clause, common in meeting minutes, as in ''there being no further questions, the meeting was closed''. ''In doing so'' links an action to its result.", "translation": "Motivos e causas também podem ser expressos por meio de orações com particípio. ''Being late for the interview, he apologized'' explica o motivo do pedido de desculpas sem usar ''because''. ''There being'' é uma forma formal de introduzir uma oração existencial, comum em atas de reunião, como em ''there being no further questions, the meeting was closed''. ''In doing so'' conecta uma ação ao seu resultado.", "question": "Where is ''there being'' commonly used, according to the text?", "options": ["In casual texting", "In meeting minutes", "In song lyrics"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000364', 'listening', 12, '{"audio_text": "Being late for the interview, he apologized immediately. There being no further questions, the meeting was closed. Considering that the budget was limited, the results were impressive.", "question": "Why did the meeting close, according to the audio?", "options": ["There being no further questions", "Because he was late", "Because the budget was limited"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000364', 'dictation', 13, '{"audio_text": "There being no further questions, the meeting was closed.", "expected": "There being no further questions, the meeting was closed."}'),
('20000000-0000-0000-0000-000000000364', 'typing', 14, '{"prompt_pt": "Traduza: ''Visto que o orçamento é limitado, e supondo que os dados estejam corretos, o plano é viável.''", "expected": "Seeing that the budget is limited, and assuming that the data is correct, the plan is feasible.", "ai_review": true}'),

