('20000000-0000-0000-0000-000000000365', 'multiple_choice', 5, '{"question": "___ the deadline cannot be extended.", "audio_text": null, "options": ["As mentioned above", "Upon arrival", "In doing so"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000365', 'matching', 6, '{"pairs": [{"left": "that said", "right": "dito isso"}, {"left": "all things considered", "right": "considerando tudo"}, {"left": "taking everything into account", "right": "levando tudo em consideração"}, {"left": "as mentioned above", "right": "como mencionado acima"}, {"left": "bearing in mind", "right": "tendo em mente"}, {"left": "with that in mind", "right": "com isso em mente"}]}'),
('20000000-0000-0000-0000-000000000365', 'fill_blank', 7, '{"sentence": "___ the risks, the team proceeded carefully.", "options": ["Bearing in mind", "That said", "Once completed"], "correct": "Bearing in mind", "translation": "Tendo em mente os riscos, a equipe prosseguiu com cuidado."}'),
