('20000000-0000-0000-0000-000000000365', 'word_order', 9, '{"words": ["The", "results", "were", "disappointing", "That", "said", "there", "is", "room", "for", "improvement"], "correct_sentence": "The results were disappointing That said there is room for improvement", "translation": "Os resultados foram decepcionantes. Dito isso, há espaço para melhorias"}'),
('20000000-0000-0000-0000-000000000365', 'word_order', 10, '{"words": ["Taking", "everything", "into", "account", "we", "decided", "to", "postpone", "the", "launch"], "correct_sentence": "Taking everything into account we decided to postpone the launch", "translation": "Levando tudo em consideração, decidimos adiar o lançamento"}'),
('20000000-0000-0000-0000-000000000365', 'reading', 11, '{"passage": "This review brings together the whole participle clauses and reduction module. ''Having'' clauses summarize completed actions, ''-ing'' and ''upon'' phrases express time, past participles like ''left unchecked'' and ''if approved'' reduce passive conditions, and reason clauses like ''seeing that'' and ''considering that'' explain causes concisely. Closing expressions such as ''that said'', ''all things considered'' and ''bearing in mind'' tie an argument together. As mentioned above, these structures are the backbone of formal, concise writing.", "translation": "Esta revisão reúne todo o módulo de orações reduzidas com particípio. Orações com ''having'' resumem ações concluídas, frases em ''-ing'' e ''upon'' expressam tempo, particípios passados como ''left unchecked'' e ''if approved'' reduzem condições passivas, e orações de razão como ''seeing that'' e ''considering that'' explicam causas de forma concisa. Expressões de fechamento como ''that said'', ''all things considered'' e ''bearing in mind'' amarram um argumento. Como mencionado acima, essas estruturas são a espinha dorsal da escrita formal e concisa.", "question": "According to the text, what do closing expressions like ''all things considered'' do?", "options": ["Introduce a new topic", "Tie an argument together", "Express uncertainty"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000365', 'listening', 12, '{"audio_text": "All things considered, the project was a success. As mentioned above, the deadline cannot be extended. With that in mind, we redesigned the entire process.", "question": "What cannot be extended, according to the audio?", "options": ["The deadline", "The budget", "The team"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000365', 'dictation', 13, '{"audio_text": "All things considered, the project was a success.", "expected": "All things considered, the project was a success."}'),
('20000000-0000-0000-0000-000000000365', 'typing', 14, '{"prompt_pt": "Traduza: ''Dito isso, e considerando tudo, o plano ainda parece a melhor opção.''", "expected": "That said, and all things considered, the plan still seems like the best option.", "ai_review": true}'),
('20000000-0000-0000-0000-000000000365', 'typing', 15, '{"prompt_pt": "Traduza: ''Tendo terminado o relatório e visto que o prazo se aproxima, ela o enviou imediatamente, tendo em mente a importância do projeto.''", "expected": "Having finished the report and seeing that the deadline was approaching, she sent it immediately, bearing in mind the importance of the project.", "ai_review": true}');

